# Comprehensive Expanded Subjective Question Bank for Class 12 (Question Bank Standards)
# Contains 210+ authentic 2m, 3m, 4m, 5m, 6m questions with full step-by-step solutions
# across all 12 core subjects (Science, Commerce, Arts, Languages).

def tag_bank(bank, board_name, class_str="12th"):
    res = []
    for q in bank:
        item = dict(q)
        item["pyqTag"] = f"{board_name} {class_str} Exam Subjective Question ({item['marks']} Marks)"
        res.append(item)
    return res

